(()=>{const root=document.documentElement;function fit(){const visible=window.visualViewport;const height=Math.round(visible&&visible.scale===1?visible.height:window.innerHeight);const viewport=Math.max(height,window.innerHeight);const full=viewport;root.style.setProperty('--app-height',full+'px');root.style.setProperty('--visible-height',viewport+'px')}fit();window.addEventListener('resize',fit);window.addEventListener('pageshow',fit);window.addEventListener('orientationchange',fit);window.visualViewport?.addEventListener('resize',fit)})();